const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Артиклі</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Німецька артикль не завжди збігається з латиською сім'єю. Тому іменники найкраще вивчати разом із артиклем.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Стаття приклади</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — табл</div>\n      <div class=\"kurss-example\">die Tür — двері</div>\n      <div class=\"kurss-example\">das Messer - ніж</div>\n      <div class=\"kurss-example\">das Mädchen - дівчина</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Часто DER</h4>\n    <p class=\"artikuli-explain\">DER часто означають особи чоловічої статі, дні, місяці, пори року та деякі слова з певними закінченнями.</p>\n\n    <h5 class=\"artikuli-subtitle\">правила</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → часто DER, наприклад: der Computer, der Lehrer <span class=\"artikuli-note\">але не завжди</span></div>\n      <div class=\"kurss-example\">-ling → часто DER, наприклад: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → часто DER, наприклад: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">особи чоловічої статі → der Mann, der Vater</div>\n      <div class=\"kurss-example\">професії → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">марки автомобілів → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">дні → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">місяці → der August, der Dezember</div>\n      <div class=\"kurss-example\">пори року → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Приклади</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — чоловічий</div>\n      <div class=\"kurss-example\">der Vater — батько</div>\n      <div class=\"kurss-example\">der Montag — понеділок</div>\n      <div class=\"kurss-example\">der August — серпень</div>\n      <div class=\"kurss-example\">der Sommer — літо</div>\n      <div class=\"kurss-example\">der Lehrer - учитель</div>\n      <div class=\"kurss-example\">der Computer - Комп'ютер</div>\n      <div class=\"kurss-example\">der Schmetterling — метелик</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Часто DIE</h4>\n    <p class=\"artikuli-explain\">DIE часто є особами жіночого роду, множина і слова, що закінчуються на -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">правила</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion ​​​​→ die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">особи жіночої статі → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">марки мотоциклів → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">множина → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">множина майже завжди → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Приклади</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau - жін</div>\n      <div class=\"kurss-example\">die Mutter — Мати</div>\n      <div class=\"kurss-example\">die Wohnung — квартира</div>\n      <div class=\"kurss-example\">die Rechnung — вексель</div>\n      <div class=\"kurss-example\">die Freiheit — свобода</div>\n      <div class=\"kurss-example\">die Möglichkeit - Можливість</div>\n      <div class=\"kurss-example\">die Mannschaft - команда</div>\n      <div class=\"kurss-example\">die Nation — Нація</div>\n      <div class=\"kurss-example\">die Universität — Університет</div>\n      <div class=\"kurss-example\">die Polizei - Поліція</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Часто DAS</h4>\n    <p class=\"artikuli-explain\">DAS часто мають зменшувальні слова з -chen / -lein, багато слів з -ment / -um і дієслова як іменники.</p>\n\n    <h5 class=\"artikuli-subtitle\">правила</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">метали → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">хімічні елементи → das Eisen, das Sauerstoff</div>\n      <div class=\"kurss-example\">готелі → das Hotel</div>\n      <div class=\"kurss-example\">кольори як іменники → das Rot, das Blau</div>\n      <div class=\"kurss-example\">дієслово як іменник → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">дієслова як іменники → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Приклади</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind - дитина</div>\n      <div class=\"kurss-example\">das Mädchen - дівчина</div>\n      <div class=\"kurss-example\">das Häuschen — котедж</div>\n      <div class=\"kurss-example\">das Instrument - інструмент</div>\n      <div class=\"kurss-example\">das Zentrum — центр</div>\n      <div class=\"kurss-example\">das Museum — Музей</div>\n      <div class=\"kurss-example\">das Essen — їжа / їжа</div>\n      <div class=\"kurss-example\">das Lernen - Навчання</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Важливо винятки / необхідно вивчати разом із статтею</h4>\n    <p class=\"artikuli-explain\">Для деяких слів артикль не можна достовірно визначити за закінченням або за латиським родом. Їх краще вивчати разом зі статтею.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — двері</div>\n      <div class=\"kurss-example\">das Messer - ніж</div>\n      <div class=\"kurss-example\">die Sonne — сонце</div>\n      <div class=\"kurss-example\">der Mond — місяць</div>\n      <div class=\"kurss-example\">das Mädchen - дівчина</div>\n      <div class=\"kurss-example\">das Auto - автомобіль</div>\n      <div class=\"kurss-example\">der Käse — сир</div>\n      <div class=\"kurss-example\">die Габель - вилка</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Закінчення та групи слів допомагають вгадати артикль, але вони не є на 100% надійним правилом. Якщо ви не впевнені, вивчіть слово з артиклем.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n            <h3>Займенники</h3>\n            <p class=\"kurss-lesson-intro\">Nominativ, Akkusativ і Dativ - Форми займенників.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Nominativ — хто?</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich — я</div><div class=\"kurss-example\">du — ви</div><div class=\"kurss-example\">er — він</div><div class=\"kurss-example\">sie — її</div><div class=\"kurss-example\">я - це</div><div class=\"kurss-example\">wir — ми</div><div class=\"kurss-example\">ihr — ви</div><div class=\"kurss-example\">sie - вони / вона</div><div class=\"kurss-example\">Sie - Ви (ввічливість)</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Akkusativ — кого?</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">mich — я</div><div class=\"kurss-example\">dich — ви</div><div class=\"kurss-example\">ihn — їх (в.)</div><div class=\"kurss-example\">sie — їх (с.)</div><div class=\"kurss-example\">Я - це</div><div class=\"kurss-example\">uns — нас</div><div class=\"kurss-example\">euch — ви</div><div class=\"kurss-example\">sie — їх / її</div><div class=\"kurss-example\">Sie - Ви (ввічливість)</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dativ — кому?</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">mir — мені</div><div class=\"kurss-example\">dir — тобі</div><div class=\"kurss-example\">ihm — для нього/це</div><div class=\"kurss-example\">ihr — їй</div><div class=\"kurss-example\">uns — для нас</div><div class=\"kurss-example\">euch — для вас</div><div class=\"kurss-example\">ihnen — для них / їм</div><div class=\"kurss-example\">Ihnen - Вам (ввічливість)</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Як вибрати форму?</h4>\n              <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — підмет речення (хто робить?)</li><li><span class=\"case-red\">Akkusativ</span> — прямий додаток (кого?)</li><li><span class=\"case-green\">Dativ</span> — непрямий додаток (кому?)</li></ul>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Приклади</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Я бачу вас.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Я бачу його.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Ти нам подобаєшся.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Я тобі допомагаю.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Даю йому книжку.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Ми дякуємо вам.</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Пам'ятай!</h4>\n              <p>Nominativ завжди є підметом речення, тоді як Akkusativ і Dativ є додатками. Подивіться на дієслово і запитайте: <span class=\"case-red\">кого?</span> або <span class=\"case-green\">кому?</span></p>\n            </section>\n",
  "kurssPronunciationLesson": "\n            <h3>Голосні - довгі і короткі</h3>\n            <p class=\"kurss-lesson-intro\">У німецькій мові голосні можуть бути довгими і короткими. Це впливає на вимову слова.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Довгий голосний</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">warm (варм) — теплий</div><div class=\"kurss-example\">gut (ґут) — добре</div><div class=\"kurss-example\">Tat (тат) - робота / дія</div><div class=\"kurss-example\">Flur (флур) — коридор</div><div class=\"kurss-example\">Weg (век) — дорога</div><div class=\"kurss-example\">Hut (гут) — капелюх</div><div class=\"kurss-example\">Hof (hōf) — двір</div><div class=\"kurss-example\">Schlaf (шлаф) - сон</div></div>\n              <p>Якщо за голосною йде одна приголосна, голосна часто вимовляється довго.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Короткий голосний</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Pilz (пілц) - гриб</div><div class=\"kurss-example\">Wort (ворт) — слово</div><div class=\"kurss-example\">Mund (мунт) — рот</div><div class=\"kurss-example\">bald (балт) - незабаром</div><div class=\"kurss-example\">scharf (шарф) — ass</div><div class=\"kurss-example\">Feld (фелт) — поль</div><div class=\"kurss-example\">voll (фол) — повн</div></div>\n              <p>Коли за голосною йдуть дві або більше приголосних, голосна часто вимовляється коротко.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Закінчення en / el / er</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">singen (зінґен) — співати</div><div class=\"kurss-example\">tragen (траґен) — nest</div><div class=\"kurss-example\">Garten (ґартен) — сад</div><div class=\"kurss-example\">Vogel (фоґел) — птах</div><div class=\"kurss-example\">Segel (зеґел) - вітрило</div><div class=\"kurss-example\">Braten (братен) - печеня</div><div class=\"kurss-example\">Bogen (bōgen) — лук</div><div class=\"kurss-example\">Spiegel (шпіґел) — дзеркало</div><div class=\"kurss-example\">Finger (фінґер) — палець</div><div class=\"kurss-example\">Halter (галтер) - держатель</div><div class=\"kurss-example\">Arbeiter (арбаітер) - робітник</div><div class=\"kurss-example\">Häuser (гоізер) - дім</div><div class=\"kurss-example\">wieder (відер) — знову</div><div class=\"kurss-example\">breiter (браітер) – ширший</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Літера h як довгота</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rahmen (рамен) — рамка</div><div class=\"kurss-example\">Ohr (ōr) — вухо</div><div class=\"kurss-example\">Kohle (kōle) — вугілля</div><div class=\"kurss-example\">Zahl (цал) - число</div><div class=\"kurss-example\">ihn (ін) — його</div><div class=\"kurss-example\">ihm (ім) — для нього</div><div class=\"kurss-example\">Huhn (гун) — курка</div><div class=\"kurss-example\">nahm (нам) — узяв</div><div class=\"kurss-example\">nehmen (немен) — брати</div><div class=\"kurss-example\">Schuh (шу) — черевик</div></div>\n              <p>У деяких словах h подовжує попередню голосну. У таких випадках h зазвичай не вимовляється.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Закінчення на e</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Lampe (лампе) — лампа</div><div class=\"kurss-example\">Hase (газе) - заєць</div><div class=\"kurss-example\">Knabe (кнабе) - хлопчик</div><div class=\"kurss-example\">Rabe (рабе) — ворон</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Довге i = ie</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">die (ді) — артикль «die»</div><div class=\"kurss-example\">diese (дізе) - це / ці</div><div class=\"kurss-example\">wieder (відер) — знову</div><div class=\"kurss-example\">Fliege (фліґе) — муха</div><div class=\"kurss-example\">Ziege (ціґе) - коза</div><div class=\"kurss-example\">Stiel (штіл) - стовб</div><div class=\"kurss-example\">Dieb (діп) — злодій</div><div class=\"kurss-example\">hier (гір) — тут</div></div>\n              <p>Довге i в німецькій мові часто пишеться як ie.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Подвоєні голосні</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Saal (зал) — трава</div><div class=\"kurss-example\">Saat (зат) — посівний</div><div class=\"kurss-example\">Staat (штат) — країна</div><div class=\"kurss-example\">Beere (бере) — ягода</div><div class=\"kurss-example\">See (зе) — озеро / море</div><div class=\"kurss-example\">Beet (бет) — постіль</div><div class=\"kurss-example\">Boot (bōt) — човен</div><div class=\"kurss-example\">Moor (mōr) — болото</div><div class=\"kurss-example\">Moos (mōs) — мох</div></div>\n              <p>Подвоєні голосні зазвичай вимовляються протяжно.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ä</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Wand (вант) — стіна</div><div class=\"kurss-example\">Wände (венде) — стіни</div><div class=\"kurss-example\">Vater (фатер) - батько</div><div class=\"kurss-example\">Väter (фетер) - батюшки</div><div class=\"kurss-example\">Schrank (шранк) — шафа</div><div class=\"kurss-example\">Schränke (шренке) - шафи</div><div class=\"kurss-example\">Bank (банк) — лава / банк</div><div class=\"kurss-example\">Bänke (бенке) - крок</div><div class=\"kurss-example\">Tal (тал) — долина</div><div class=\"kurss-example\">Täler (телер) — долини</div></div>\n              <p>ä - це налаштування a.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ö</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rose (rōze) — троянда</div><div class=\"kurss-example\">Röschen (ресхен) — розетка</div><div class=\"kurss-example\">Ofen (ōfen) — піч</div><div class=\"kurss-example\">Öfen (ефен) — печі</div><div class=\"kurss-example\">Rock (рок) — спідниця</div><div class=\"kurss-example\">Röcke (röke) — Спідниця</div></div>\n              <p>ö — це налаштування о.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ü</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kurz (курц) — корот</div><div class=\"kurss-example\">kürzer (курцер) — корот</div><div class=\"kurss-example\">Kunst (кунст) — ст</div><div class=\"kurss-example\">Künste (künste) — ст</div><div class=\"kurss-example\">Mutter (мутер) — мати</div><div class=\"kurss-example\">Mütter (муттер) — матері</div></div>\n              <p>ü - це налаштування u.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Дифтонги: äu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Baum (баум) — дерево</div><div class=\"kurss-example\">Bäume (боіме) — дерева</div><div class=\"kurss-example\">Haus (гаус) — будинок</div><div class=\"kurss-example\">Häuser (гоізер) - дім</div><div class=\"kurss-example\">Strauch (штрауг) — кущ</div><div class=\"kurss-example\">Sträucher (штроігер) — кущі</div><div class=\"kurss-example\">Maus (маус) — миша</div><div class=\"kurss-example\">Mäuse (моізе) - миші</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Дифтонги: eu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">heute (гоіте) — сьогодні</div><div class=\"kurss-example\">Leute (лоіте) - чол</div><div class=\"kurss-example\">neu (ноі) - нов</div><div class=\"kurss-example\">neun (ноін) — дев'ять</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Дифтонги: ei</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">mein (маін) - моє</div><div class=\"kurss-example\">dein (даін) — ваш</div><div class=\"kurss-example\">sein (заін) — вона / її / бути</div><div class=\"kurss-example\">frei (фраі) — вільний</div><div class=\"kurss-example\">arbeiten (арбаітен) - працювати</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Лекція 2 нотатки вимови</h4>\n              <ul class=\"kurss-summary-list\"><li>у словах ich, nicht, rechnen, zeichnen «ch» вимовляється м'яко</li><li>у словах arbeiten і zeichnen «ei» вимовляється як «ай»</li><li>«сп» на початку слова вимовляється як «шп»</li><li>у дієслові tun буква «у» вимовляється протяжно</li></ul>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Резюме</h4>\n              <ul class=\"kurss-summary-list\"><li>один приголосний після голосного → часто довгий голосний</li><li>два або більше приголосних → часто короткий голосний</li><li>h може подовжувати голосний</li><li>ie часто стоїть на довгому i</li><li>подвоєні голосні зазвичай довгі</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Приголосні і буквосполучення</h3>\n            <p class=\"kurss-lesson-intro\">У німецькій мові деякі приголосні та буквосполучення вимовляються інакше, ніж пишуться. Ця лекція містить найважливіші приклади для початківця.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Приголосні</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">das Rad (рат) — колесо</div><div class=\"kurss-example\">die Räder (редер) — колеса</div><div class=\"kurss-example\">Bad (бат) — ванна</div><div class=\"kurss-example\">Bäder (бедер) — бані</div></div>\n              <p>Приголосні в кінці слова часто вимовляються не так, як пишуться.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>гл</h4>\n              <p>\"ch\" можна вимовляти м'яко або твердо. В одних словах звучить як «ч», в інших ближче до «к».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">rechnen (регнен) - обчислювати</div><div class=\"kurss-example\">zeichnen (цаігнен) — малювати</div><div class=\"kurss-example\">nicht (нігт) — ні</div><div class=\"kurss-example\">schlecht (шлегт) — погано</div><div class=\"kurss-example\">mich (міг) — я</div><div class=\"kurss-example\">dich (діг) — ти</div><div class=\"kurss-example\">Strauch (штрауг) — кущ</div><div class=\"kurss-example\">noch (ног) - більше</div><div class=\"kurss-example\">Nacht (нагт) — ніч</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sch</h4>\n              <p>«sch» німецькою мовою вимовляється як латиська «š».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Schule (шуле) — школа</div><div class=\"kurss-example\">Schüler (шулер) - учень</div><div class=\"kurss-example\">Schiff (шіф) - корабель</div><div class=\"kurss-example\">Schraube (шраубе) - гвинт</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sp і st на початку слова</h4>\n              <p>На початку слова чи складу «sp» часто вимовляється як «šp», а «st» — як «št».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen (шпілен) - грати</div><div class=\"kurss-example\">Sprung (шпрунґ) — стрибок</div><div class=\"kurss-example\">stehen (штеен) — стояти</div><div class=\"kurss-example\">Stall (штал) - сарай</div><div class=\"kurss-example\">Stand (штант) - стан / місце</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>qu</h4>\n              <p>\"qu\" зазвичай вимовляється як \"kv\" німецькою мовою.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Qual (квал) — агонія</div><div class=\"kurss-example\">Quartier (квартір) - квартал / проживання</div><div class=\"kurss-example\">quer (квер) — поперек</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>s і z</h4>\n              <p>«s» часто звучить як «z» на початку слова. Буква «z» німецькою мовою звучить як латиське «c».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">sagen (заґен) — сказати</div><div class=\"kurss-example\">singen (зінґен) — співати</div><div class=\"kurss-example\">Rose (rōze) — троянда</div><div class=\"kurss-example\">Zahl (цал) - число</div><div class=\"kurss-example\">Zeit (цаіт) — час</div><div class=\"kurss-example\">Zink (цінк) – цинк</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>v</h4>\n              <p>У німецькій мові «v» часто вимовляється як «f». В іноземних словах часто звучить як латиське «v».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Vater (фатер) - батько</div><div class=\"kurss-example\">von (фон) — від</div><div class=\"kurss-example\">viel (філ) - багато</div><div class=\"kurss-example\">vier (фір) — чотири</div><div class=\"kurss-example\">Villa (вілла) - вілла</div><div class=\"kurss-example\">Klavier (клавір) - фортепіано</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>x і y</h4>\n              <p>\"х\" вимовляється як \"кс\". \"у\" в деяких словах вимовляється як \"ü\".</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Felix (фелікс) - Фелікс</div><div class=\"kurss-example\">Axt (акст) — сокира</div><div class=\"kurss-example\">Mystik (мустік) — містика</div><div class=\"kurss-example\">Nyx (нукс) - Нікса</div><div class=\"kurss-example\">Mythe (муте) - міф</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ß</h4>\n              <p>\"ß\" німецькою мовою вимовляється як \"s\".</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Fuß (фус) — стопа</div><div class=\"kurss-example\">Füße (фусе) — стопи</div><div class=\"kurss-example\">Grüße (ґрусе) - вітання</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Резюме</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → š</li><li>sp / st на початку → šp / št</li><li>qu → кв</li><li>z → c</li><li>v часто → f</li><li>x → ks</li><li>ß → s</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Основи дієслова</h3>\n            <p class=\"kurss-lesson-intro\">Лекції 1 дієслова і флексії.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Дієслова</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kommen — прийти</div><div class=\"kurss-example\">gehen — йде</div><div class=\"kurss-example\">stehen — стояти</div><div class=\"kurss-example\">singen — співати</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>kommen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich komme - Я йду</div><div class=\"kurss-example\">du kommst — ти приходиш</div><div class=\"kurss-example\">er kommt - він іде</div><div class=\"kurss-example\">sie kommt - вона йде</div><div class=\"kurss-example\">wir kommen - ми йдемо</div><div class=\"kurss-example\">ihr kommt - Ви йдете</div><div class=\"kurss-example\">sie kommen - вони / вони йдуть</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>gehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich gehe - Я йду</div><div class=\"kurss-example\">du gehst — ви йдете</div><div class=\"kurss-example\">er geht - він іде</div><div class=\"kurss-example\">sie geht - вона йде</div><div class=\"kurss-example\">wir gehen - йдемо</div><div class=\"kurss-example\">ihr geht - ви йдете</div><div class=\"kurss-example\">sie gehen - вони / вона йде</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>stehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich stehe - Я стою</div><div class=\"kurss-example\">du stehst - стоїш</div><div class=\"kurss-example\">er steht - він стоїть</div><div class=\"kurss-example\">sie steht - вона стоїть</div><div class=\"kurss-example\">wir stehen - стоїмо</div><div class=\"kurss-example\">ihr steht - Ви стоїте</div><div class=\"kurss-example\">sie stehen - вони / вона стоїть</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>singen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich singe - співаю</div><div class=\"kurss-example\">du singst — співаєш</div><div class=\"kurss-example\">er singt - співає він</div><div class=\"kurss-example\">sie singt - співає вона</div><div class=\"kurss-example\">wir singen - співаємо</div><div class=\"kurss-example\">ihr singt - Ви співаєте</div><div class=\"kurss-example\">sie singen - вони / вона співає</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>2. лекції дієслова</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen — грати</div><div class=\"kurss-example\">arbeiten — працювати</div><div class=\"kurss-example\">fragen — запитувати</div><div class=\"kurss-example\">antworten - відповісти</div><div class=\"kurss-example\">rechnen — рахувати</div><div class=\"kurss-example\">zeichnen — малювати</div><div class=\"kurss-example\">tun — робити</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>spielen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich spiele - Я граю</div><div class=\"kurss-example\">du spielst - ви граєте</div><div class=\"kurss-example\">er spielt - Він грає</div><div class=\"kurss-example\">sie spielt - вона грає</div><div class=\"kurss-example\">wir spielen - Ми граємо</div><div class=\"kurss-example\">ihr spielt - Ви граєте</div><div class=\"kurss-example\">sie spielen - вони / вона грає</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>arbeiten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich arbeite - Я працюю</div><div class=\"kurss-example\">du арбетест - ви працюєте</div><div class=\"kurss-example\">er arbeitet - він працює</div><div class=\"kurss-example\">sie arbeitet - вона працює</div><div class=\"kurss-example\">wir arbeiten - ми працюємо</div><div class=\"kurss-example\">ihr arbeitet - Ви працюєте</div><div class=\"kurss-example\">sie arbeiten - вони / вони працюють</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>fragen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich frage - запитав я</div><div class=\"kurss-example\">du fragst - запитаєте ви</div><div class=\"kurss-example\">er fragt - питає він</div><div class=\"kurss-example\">sie fragt - питає вона</div><div class=\"kurss-example\">wir fragen - запитуємо</div><div class=\"kurss-example\">ihr fragt - запитаєте ви</div><div class=\"kurss-example\">sie fragen - вони / вони запитують</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>antworten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich antworte - відповідаю</div><div class=\"kurss-example\">du antwortest - ви відповідаєте</div><div class=\"kurss-example\">er antwortet - відповідає він</div><div class=\"kurss-example\">sie antwortet - відповідає вона</div><div class=\"kurss-example\">wir antworten - відповідаємо</div><div class=\"kurss-example\">ihr antwortet - ви відповідаєте</div><div class=\"kurss-example\">sie antworten - вони / вони відповідають</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>rechnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich rechne - обчислюю</div><div class=\"kurss-example\">du rechnest - обчислюєш</div><div class=\"kurss-example\">er rechnet - він обчислює</div><div class=\"kurss-example\">sie rechnet - вона обчислює</div><div class=\"kurss-example\">wir rechnen - рахуємо</div><div class=\"kurss-example\">ihr rechnet - обчислюєте</div><div class=\"kurss-example\">sie rechnen - вони / її рахунок</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>zeichnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich zeichne - малюю</div><div class=\"kurss-example\">du zeichnest - малюєш</div><div class=\"kurss-example\">er zeichnet - він малює</div><div class=\"kurss-example\">sie zeichnet — вона малює</div><div class=\"kurss-example\">wir zeichnen - малюємо</div><div class=\"kurss-example\">ihr zeichnet - ви малюєте</div><div class=\"kurss-example\">sie zeichnen - вони / вона малює</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>tun</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich вт — я роблю</div><div class=\"kurss-example\">du tust — ви робите</div><div class=\"kurss-example\">er tut - він робить</div><div class=\"kurss-example\">sie tut - вона робить</div><div class=\"kurss-example\">wir tun - Ми робимо</div><div class=\"kurss-example\">ihr tut - ви робите</div><div class=\"kurss-example\">sie tun - вони / вони роблять</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Будова речень</h3>\n            <p class=\"kurss-lesson-intro\">дієслово зазвичай стоїть першим у питальному реченні німецькою мовою.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Приклади</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Du kommst. - Ти приходь.</div><div class=\"kurss-example\">Kommst du? — Ти йдеш?</div><div class=\"kurss-example\">Er singt. — Він співає.</div><div class=\"kurss-example\">Singt er? — Він співає?</div><div class=\"kurss-example\">Запуск du? — Ти стоїш?</div><div class=\"kurss-example\">Якщо, ich stehe. — Так, я стою.</div><div class=\"kurss-example\">Geht ihr? — Ви йдете?</div><div class=\"kurss-example\">Якщо, wir gehen. - Так, ми йдемо.</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Питання з \"was\"</h4>\n              <p>Якщо питання починається з питального слова, дієслово у німецькій мові зазвичай стоїть відразу після питального слова.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Was tut du? — Що ти робиш?</div><div class=\"kurss-example\">Was tut er? - Що він робить?</div><div class=\"kurss-example\">Was tut sie? «Що вона робить?»</div><div class=\"kurss-example\">Was tun sie? — Що вони роблять?</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Заперечення з \"nicht\"</h4>\n              <p>Коли заперечення \"nicht\" відноситься до дієслова, воно зазвичай стоїть після дієслова в німецькій мові.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich spiele nicht. — Я не граю.</div><div class=\"kurss-example\">Павло fragt nicht. — Павло не питає.</div><div class=\"kurss-example\">Er kommt nicht. — Він не прийде.</div><div class=\"kurss-example\">Sie singen nicht. — Вони / вони не співають.</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Речення з 2 лекції</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Spielst du? — Ти граєш?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Ні, я не граю, я працюю.</div><div class=\"kurss-example\">Павло fragt nicht, er arbeitet. — Павло не питає, він працює.</div><div class=\"kurss-example\">Arbeitest du? - Ви працюєте?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Ні, я не працюю, я співаю.</div><div class=\"kurss-example\">Was tut Павло? - Що робить Павло?</div><div class=\"kurss-example\">Er spielt. — Він грає.</div><div class=\"kurss-example\">Was tut Marie? - Що робить Марі?</div><div class=\"kurss-example\">Sie singt. — Вона співає.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Пауль грає, а Марі співає.</div><div class=\"kurss-example\">Singt ihr? — Ти співаєш?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Ні, ми не співаємо, ми працюємо.</div><div class=\"kurss-example\">Was tun Paul und Marie? - Що роблять Пауль і Марі?</div><div class=\"kurss-example\">Sie fragen. — запитують.</div><div class=\"kurss-example\">Sie antworten nicht. — Не відповідають.</div><div class=\"kurss-example\">Wer arbeitet? - Хто працює?</div><div class=\"kurss-example\">Wir arbeiten. — Ми працюємо.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Рахуємо і малюємо.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Приходять, запитують, відповідають, працюють, грають, співають і йдуть.</div></div>\n            </section>",
  "kurssLesson2": "            <h3>Лекція 2</h3>\n            <p class=\"kurss-lesson-intro\">Друга лекція: діалоги, слова, вимова, граматика та переклад.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Діалоги / речення</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — грати; грати</div>\n                  <div class=\"kurss-example\">nein - ні</div>\n                  <div class=\"kurss-example\">nicht — ні</div>\n                  <div class=\"kurss-example\">arbeiten — працювати</div>\n                  <div class=\"kurss-example\">fragen — запитувати</div>\n                  <div class=\"kurss-example\">was tut er? — що він робить?</div>\n                  <div class=\"kurss-example\">was tun sie? — що вони/вони роблять?</div>\n                  <div class=\"kurss-example\">aber — але</div>\n                  <div class=\"kurss-example\">antworten - відповісти</div>\n                  <div class=\"kurss-example\">rechnen — рахувати</div>\n                  <div class=\"kurss-example\">zeichnen — малювати</div>\n                  <div class=\"kurss-example\">Marie - Марі</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Вимова</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">У словах ich, nicht, rechnen, zeichnen звук ch вимовляється м'яко, приблизно як у латиських словах: technika, Fridrichs.</div><div class=\"kurss-example\">У словах arbeiten, zeichnen дифтонг ei вимовляється приблизно як латиський плоский звук e, після якого йде і.</div><div class=\"kurss-example\">Група приголосних sp вимовляється як šp: spielen (шпілен).</div><div class=\"kurss-example\">У дієслові tun у вимовляється протяжно в усіх особах.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Закінчення на e</h4>\n                  <div class=\"lesson1-grammar-note\">Якщо основа дієслова закінчується на t, d, chn, то e при відмінюванні стоїть перед закінченнями -st і -t.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Питальне слово</h4>\n                  <div class=\"lesson1-grammar-note\">У питальних реченнях, які починаються питальним словом, наприклад: кого? хто? хто? чому? чому? тощо, дієслово стоїть безпосередньо після питального слова.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tut du? — Що ти робиш?</div><div class=\"kurss-example\">Was tut er? - Що він робить?</div><div class=\"kurss-example\">Was tut sie? «Що вона робить?»</div><div class=\"kurss-example\">Was tun sie? — Що вони роблять?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Заперечення з nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Якщо заперечення nicht відноситься до дієслова, то заперечне слово стоїть після дієслова.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — Він не прийде.</div><div class=\"kurss-example\">Sie singen nicht. — Вони не співають.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Перекласти</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Картка перекладу лекції 2\">\n                    <span class=\"lesson1-training-progress\">Лекція 2 · Переклад: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Хто питає?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Натисніть на картку, щоб побачити переклад німецькою мовою. Після відповіді наступне клацання показує наступну картку.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson6": "\n    <h3>Лекція 6</h3>\n    <p class=\"kurss-lesson-intro\">Числа, множина, умляути та форми множини іменників.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Діалоги / речення</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — розташований, знаходиться, лежить</div><div class=\"kurss-example\">der Bleistift (блеіштіфт) — олівець</div><div class=\"kurss-example\">einige (еініґе) - деякі</div><div class=\"kurss-example\">hinlegen - відкласти</div><div class=\"kurss-example\">legt hin - поставити</div><div class=\"kurss-example\">wieder (відер) — знову</div><div class=\"kurss-example\">aufmachen — розв'язувати</div><div class=\"kurss-example\">er macht auf - він розв'язує</div><div class=\"kurss-example\">anspitzen (аншпіцен) - поставити точку</div><div class=\"kurss-example\">er spitzt an - він плює</div><div class=\"kurss-example\">sich setzen - сісти</div><div class=\"kurss-example\">setzt sich - сідає</div><div class=\"kurss-example\">der Schlüssel (шлусел) - ключ</div><div class=\"kurss-example\">das Fenster (фенстер) - вікно</div><div class=\"kurss-example\">die Tafel (ді тафел) — дошка</div><div class=\"kurss-example\">der Garten — сад</div><div class=\"kurss-example\">der Löffel — ложка</div><div class=\"kurss-example\">zählen (целен) - рахувати</div><div class=\"kurss-example\">die Nadel - голка</div><div class=\"kurss-example\">was ist das - Що це?</div><div class=\"kurss-example\">der Hammer — кувалда</div><div class=\"kurss-example\">die Hämmer - молотки</div><div class=\"kurss-example\">der Deckel (дер декел) — кришка</div><div class=\"kurss-example\">der Teller — Тарілка</div><div class=\"kurss-example\">der Wagen — Колісниця</div><div class=\"kurss-example\">der Schlitten — сани, сани</div><div class=\"kurss-example\">das Ding — відмінок</div><div class=\"kurss-example\">die Dinge - речі</div><div class=\"kurss-example\">wie sind die Dinge? — як справи?</div><div class=\"kurss-example\">voll (fōl) — повн</div><div class=\"kurss-example\">leer (лер) - порожній</div><div class=\"kurss-example\">schwer (швер) — важкий, важкий</div><div class=\"kurss-example\">leicht - світло</div><div class=\"kurss-example\">der Eimer — відро</div><div class=\"kurss-example\">wieviel (віфіл) - скільки</div><div class=\"kurss-example\">wieviel Nadeln - скільки голок</div><div class=\"kurss-example\">hier (гір) — тут</div><div class=\"kurss-example\">dort — там</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Вимова</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä є редуплікацією голосної a і вимовляється як короткий або довгий вузький e.</div><div class=\"kurss-example\">Приклади: das Mädchen (метхен), die Bänke (ді бенке), der Vater (дер фатер), die Väter (ді фетер).</div><div class=\"kurss-example\">ü обертон голосного u. При його вимові губи повинні бути сильно округленими і намагатися вимовляти і круглими губами.</div><div class=\"kurss-example\">Приклади: fünf, der Schlüssel (шлусел).</div><div class=\"kurss-example\">ö вимовляти округлими губами, намагаючись вимовити e: der Löffel.</div><div class=\"kurss-example\">Подвоєний голосний символізує довгий голосний: leer (лер).</div><div class=\"kurss-example\">Дифтонг eu вимовляється як oi: neun (ноін).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Граматика і пояснення</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Наголошений префікс складного дієприслівника відокремлюється від дієслова теперішнього часу і стоїть у кінці речення.</div><div class=\"kurss-example\">Приклади: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">Числівне слово є одним у всіх трьох порядках, коли воно вживається з іменником: у чоловічому роді ein, у жіночому — eine, у середньому — ein.</div><div class=\"kurss-example\">Приклади: ein Schüler — один учень; eine Schülerin — один учень; ein Kind — одна дитина.</div><div class=\"kurss-example\">Цифри: eins, zwei, drei, vier (фір), fünf, sechs (zek), sieben (блимає), acht, neun (noin), zehn (cén).</div><div class=\"kurss-example\">Saitaina в німецькій мові має форми однини та множини: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Зазначені займенник змінюються за кількістю та порядком у латиській мові, але в німецькій мові використовується одна форма: das.</div><div class=\"kurss-example\">Приклади: це кувалда — das ist ein Hammer; це голка — das ist eine Nadel; це молотки — das sind Hämmer; це голки — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — візки та der Schlitten — сани є множинними в латиській мові, але в німецькій мові ці слова вживаються в в однині та в множині.</div><div class=\"kurss-example\">Чоловічий і середній рід іменники, що закінчуються на -er, -el, -en в множині часто не мають закінчення.</div><div class=\"kurss-example\">Приклади: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Жіночий відмінок іменники із закінченням -el, -er в множині приймає -n.</div><div class=\"kurss-example\">Приклади: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Винятки: die Mutter (мате) — die Mütter (матері); die Tochter (дочка) — die Töchter (доньки).</div><div class=\"kurss-example\">Неозначений артикль не має множини: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">У розповідному реченні на другому місці стоїть мовник-дієслово: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Перекласти</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Картка перекладу лекції 6\"><span class=\"lesson1-training-progress\">Лекція 6 · Переклад: 1 / 21</span><span class=\"lesson1-training-text\">Павло бере олівець і малює.</span></button><p class=\"lesson1-training-hint\">Натисніть на картку, щоб побачити переклад німецькою мовою. Після відповіді наступне клацання показує наступну картку.</p></div></div>\n    </details>\n  ",
  "kurssLesson5": "\n    <h3>Лекція 5</h3>\n    <p class=\"kurss-lesson-intro\">Закінчення Wen?, знахідний відмінок, sitzen, fragen і -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Діалоги / речення</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (зіцен) — сидіти</div>\n        <div class=\"kurss-example\">fragen (фраґен) - запитувати</div>\n        <div class=\"kurss-example\">der Lehrer (дер лерер) - учитель</div>\n        <div class=\"kurss-example\">gut (ґут) - добре</div>\n        <div class=\"kurss-example\">wen (вен) — що</div>\n        <div class=\"kurss-example\">loben — хвалити</div>\n        <div class=\"kurss-example\">der Schüler (шулер) - учень</div>\n        <div class=\"kurss-example\">klein — мал</div>\n        <div class=\"kurss-example\">groß (grōs) — великий</div>\n        <div class=\"kurss-example\">die Lehrerin - учитель</div>\n        <div class=\"kurss-example\">die Schülerin - школярка</div>\n        <div class=\"kurss-example\">schlecht (шлегт) - погано</div>\n        <div class=\"kurss-example\">tadeln — шкурка</div>\n        <div class=\"kurss-example\">oder (ōder) — або</div>\n        <div class=\"kurss-example\">das Kind (кінт) — дит</div>\n        <div class=\"kurss-example\">artig (артіх) — пройдисвіт</div>\n        <div class=\"kurss-example\">die Mutter — Мати</div>\n        <div class=\"kurss-example\">lieben (лібен) - любити</div>\n        <div class=\"kurss-example\">der Vater (фатер) - батько</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Вимова</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz — подвоєний звук z і вимовляється як z: sitzen (зіцен).</div>\n        <div class=\"kurss-example\">v у німецьких словах вимовляється як f: der Vater (фатер).</div>\n        <div class=\"kurss-example\">ß називається escet і вимовляється як латиський s: groß (grōs), weiß (veis).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Називний відмінок і знахідний відмінок</h4><div class=\"lesson1-grammar-note\">У латиській мові називний відмінок відповідає на питання хто?, а знахідний відмінок відповідає на питання кого?.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Німецькою мовою питання називному відмінку є wer? осіб і was? предметів.</div><div class=\"kurss-example\">Знахідному відмінку питання wen? осіб і was? предметів.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Зміна статті знахідному відмінку</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + знахідний відмінок</h4><div class=\"lesson1-grammar-note\">Дієслово fragen у німецькій мові вимагає знахідного відмінка.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">-in закінчення</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Багато іменників жіночого роду походять із закінченням -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Місце дієслова</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">У розповідному реченні дієслово стоїть на другому місці.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Перекласти</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Картка перекладу лекції 5\"><span class=\"lesson1-training-progress\">Лекція 5 · Переклад: 1 / 16</span><span class=\"lesson1-training-text\">Що любить батько?</span></button><p class=\"lesson1-training-hint\">Натисніть на картку, щоб побачити переклад німецькою мовою. Після відповіді наступне клацання показує наступну картку.</p></div></div>\n    </details>\n  ",
  "kurssLesson4": "            <h3>Лекція 4</h3>\n            <p class=\"kurss-lesson-intro\">Знахідний відмінок, nehmen, hinlegen, hinausgehen і прикметники.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Діалоги / речення</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? I legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, I ist nicht stumpf, I ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (немен) — брати</div><div class=\"kurss-example\">er nimmt (німт) — бере</div><div class=\"kurss-example\">der Federhalter (дер федергалтер) - ручка</div><div class=\"kurss-example\">einen Federhalter - пір'яний недоуздок</div><div class=\"kurss-example\">zeigen - показати</div><div class=\"kurss-example\">schwarz (шварц) - чорний</div><div class=\"kurss-example\">weiß (веіс) - білий</div><div class=\"kurss-example\">die Feder (ді федер) — перо</div><div class=\"kurss-example\">eine Feder — перо</div><div class=\"kurss-example\">spitz (шпіц) — загострений</div><div class=\"kurss-example\">hinlegen - відкласти</div><div class=\"kurss-example\">legt hin - поставити</div><div class=\"kurss-example\">das Mädchen (метхен) - дівчина</div><div class=\"kurss-example\">das Messer - ніж</div><div class=\"kurss-example\">ein Messer - ніж</div><div class=\"kurss-example\">scharf — ass</div><div class=\"kurss-example\">stumpf (штумпф) — тупий, тупий</div><div class=\"kurss-example\">dann — тоді</div><div class=\"kurss-example\">hinaus — виход</div><div class=\"kurss-example\">hinausgehen - вийти, вийти</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Вимова</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Закінчення -en, -er, -el ненаголошені, тому e у цих закінченнях чутно слабо: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">h у німецькій мові може бути як звуком, так і маркером тривалості попереднього голосного.</div><div class=\"kurss-example\">Якщо h довге, воно не вимовляється як звук: nehmen (немен).</div><div class=\"kurss-example\">Якщо після голосного стоїть лише один приголосний, голосний вимовляється протяжно: die (ді) Feder (федер), den (ден).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Знахідний відмінок</h4><div class=\"lesson1-grammar-note\">У жіночому та середньому родах знахідний відмінок дорівнює називному відмінку. Змінюється лише черга чоловіків.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Займенники</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er - чоловіча черга</div><div class=\"kurss-example\">sie - жіноча черга</div><div class=\"kurss-example\">я - середній круглий</div><div class=\"kurss-example\">в множині — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Знімні дієслова</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Прикметники</h4><div class=\"lesson1-grammar-note\">Якщо прикметник має додаток у реченні, він не змінюється ні за відмінком, ні за числом.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Заперечення з nicht</h4><div class=\"lesson1-grammar-note\">Якщо nicht заперечує прикметник, він стоїть перед запереченим словом.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Іменники, що закінчуються на -chen і -lein, знаходяться в середньому порядку: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Перекласти</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Картка перекладу лекції 4\"><span class=\"lesson1-training-progress\">Лекція 4 · Переклад: 1 / 16</span><span class=\"lesson1-training-text\">Дівчина бере перо древка.</span></button><p class=\"lesson1-training-hint\">Натисніть на картку, щоб побачити переклад німецькою мовою. Після відповіді наступне клацання показує наступну картку.</p></div></div></details>",
  "kurssLesson3": "            <h3>Лекція 3</h3>\n            <p class=\"kurss-lesson-intro\">Третя лекція: діалоги, слова, вимова, граматика та переклад.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Діалоги / речення</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — що</div><div class=\"kurss-example\">was — що</div><div class=\"kurss-example\">hier — тут</div><div class=\"kurss-example\">dort — там</div><div class=\"kurss-example\">der Tisch — табл</div><div class=\"kurss-example\">ein Tisch — табл</div><div class=\"kurss-example\">die Bank — лавка</div><div class=\"kurss-example\">eine Bank — лавка</div><div class=\"kurss-example\">liegen - лежачи</div><div class=\"kurss-example\">liegt hier ein Buch? — чи є тут книга?</div><div class=\"kurss-example\">das Buch — книга</div><div class=\"kurss-example\">ein Buch — книга</div><div class=\"kurss-example\">hängen - повісити</div><div class=\"kurss-example\">das Bild - малюнок</div><div class=\"kurss-example\">ein Bild - малюнок</div><div class=\"kurss-example\">die Tafel - Дошка</div><div class=\"kurss-example\">eine Tafel - Дошка</div><div class=\"kurss-example\">wie - хтось, хтось</div><div class=\"kurss-example\">ist — є</div><div class=\"kurss-example\">dick — товстий, жирний</div><div class=\"kurss-example\">das Heft - зошит</div><div class=\"kurss-example\">ein Heft - зошит</div><div class=\"kurss-example\">dünn — тонкий, тонкий</div><div class=\"kurss-example\">niedrig — низький</div><div class=\"kurss-example\">hoch — високий</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Вимова</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Довгий звук ī у німецькій мові представлений іе: liegen (ліґен), hier (гір), wie (ві).</div><div class=\"kurss-example\">ck є подвійним k: dick (дікк).</div><div class=\"kurss-example\">У прикметниках і прислівниках закінчення -ig звучить як легкий -ich: niedrig (нідріх).</div><div class=\"kurss-example\">Якщо закінчення -ig закінчується на e: -ige, то g вимовляється як певний звук g: niedrige (нідріґе) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Підмет речення</h4><div class=\"lesson1-grammar-note\">Підмет речення в німецькій мові відповідає на питання wer? / was? і стоїть називному відмінку.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">З wer? запитує осіб.</div><div class=\"kurss-example\">З was? просить предмети.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Артиклі</h4><div class=\"lesson1-grammar-note\">У німецькій мові іменник має 3 відмінки: чоловічий, жіночий і середній. Перед іменниками зазвичай стоїть слово, яке називається артиклем. Це слово не перекладається.</div><h5 class=\"lesson2-subtitle\">Деякі артикль</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">чоловічий тур - der</div><div class=\"kurss-example\">жіноча черга - die</div><div class=\"kurss-example\">середній раунд - das</div><div class=\"kurss-example\">В множині, визначений артикль для всіх трьох порядків, є die.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Невизначений артикль</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">чоловічий тур - ein</div><div class=\"kurss-example\">жіноча черга - eine</div><div class=\"kurss-example\">середній раунд - ein</div><div class=\"kurss-example\">Неозначений артикль не має множини.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Власні іменники</h4><div class=\"lesson1-grammar-note\">Артикль не вживається перед власними іменниками.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Місце дієслова</h4><div class=\"lesson1-grammar-note\">У розповідному реченні дієслово стоїть на другому місці.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Німецькою мовою для об’єктів, що стоять вертикально, кажуть, що об’єкт стоїть:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Кажуть, що предмети, розташовані горизонтально, лежать:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Предмети також можна повісити:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Перекласти</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Картка перекладу лекції 3\"><span class=\"lesson1-training-progress\">Лекція 3 · Переклад: 1 / 22</span><span class=\"lesson1-training-text\">ти рахуєш</span></button><p class=\"lesson1-training-hint\">Натисніть на картку, щоб побачити переклад німецькою мовою. Після відповіді наступне клацання показує наступну картку.</p></div></div></details>",
  "kurssLesson7": "            <h3>Лекція 7</h3>\n            <p class=\"kurss-lesson-intro\">Сьома лекція: вираження наказу, форма звернення та множина.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Діалоги / речення</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — співати</div><div class=\"kurss-example\">singe – співати</div><div class=\"kurss-example\">singt — Спів</div><div class=\"kurss-example\">singen Sie - Спів</div><div class=\"kurss-example\">das Lied (дас літ) — пісня</div><div class=\"kurss-example\">Sie — Ви</div><div class=\"kurss-example\">zählen - кол</div><div class=\"kurss-example\">das Fräulein (фроілеін) — міс</div><div class=\"kurss-example\">der Müller — Мельник</div><div class=\"kurss-example\">öffnen - відкритий</div><div class=\"kurss-example\">das Fenster (фенстер) - вікно</div><div class=\"kurss-example\">alle - кожен</div><div class=\"kurss-example\">der Spiegel (шпіґел) — дзеркало</div><div class=\"kurss-example\">der Lappen — ганчірка, швабра</div><div class=\"kurss-example\">der Spaten — пік</div><div class=\"kurss-example\">der Besen — мітла</div><div class=\"kurss-example\">die Schaufel — лезо</div><div class=\"kurss-example\">die Schüssel — миска</div><div class=\"kurss-example\">das Zimmer — кімната</div><div class=\"kurss-example\">das Ufer (уфер) — берег</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Вимова</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp на початку слова чи складу вимовляється як šp: der Spiegel (дер шпіґел).</div><div class=\"kurss-example\">sch вимовляється як латиське š: die Schaufel (ді шауфел), die Schüssel (ді шусел).</div><div class=\"kurss-example\">Дифтонг äu вимовляється як латиська oi: das Fräulein (дас фроілеін).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Командний вираз</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Наказовий вислів у 2-й особі однини відповідає 2-й особі дієслова в однині без особового закінчення -st, додаючи закінчення -e.</div><div class=\"kurss-example\">Приклади: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Дуже часто закінчення -e не вживається, якщо з ним форма наказу стає односкладовою: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Команда множини</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Наказовий спосіб у 2-й особі в множині подібний до 2-ї особи множини в теперішній часs, але вживається без займенника.</div><div class=\"kurss-example\">Приклади: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Форма мови з Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Форма звернення на «Ви» нагадує 3-ю особу множини. Займенник Sie пишеться з великої літери і стоїть після дієслова.</div><div class=\"kurss-example\">Приклади: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Для дієслова öffnen для легшої вимови в 2-й і 3-й особі в однині і в 2-й особі в множині, e вставляється між основою і закінченням: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Вправа</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Картка з вправою лекція 7\"><span class=\"lesson1-training-progress\">Лекція 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — запитувати</span></button><p class=\"lesson1-training-hint\">Торкніться картки, щоб побачити форми команд.</p></div></div></details>",
  "kurssLesson1": "            <h3>Лекція 1</h3>\n            <p class=\"kurss-lesson-intro\">Перша лекція: дієслова у теперішньому часі, слова, вимова, граматика та переклад.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Дієслова в теперішньому часі</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Дієслова та їх відмінювання в теперішньому часі.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — прийти</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>я йду</span><span>du</span><strong>kommst</strong><span>ти приходиш</span><span>er / sie</span><strong>kommt</strong><span>він/вона приходить</span><span>wir</span><strong>kommen</strong><span>ми йдемо</span><span>ihr</span><strong>kommt</strong><span>ти йдеш</span><span>sie / Sie</span><strong>kommen</strong><span>вони / ти йдеш</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — йде</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>я йду</span><span>du</span><strong>gehst</strong><span>ти йдеш</span><span>er / sie</span><strong>geht</strong><span>він / вона йде</span><span>wir</span><strong>gehen</strong><span>ми йдемо</span><span>ihr</span><strong>geht</strong><span>ти йдеш</span><span>sie / Sie</span><strong>gehen</strong><span>вони / ти йдеш</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — стояти</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>я стою</span><span>du</span><strong>поспішаючи</strong><span>ви стоїте</span><span>er / sie</span><strong>steht</strong><span>він/вона стоїть</span><span>wir</span><strong>stehen</strong><span>ми стоїмо</span><span>ihr</span><strong>steht</strong><span>ви стоїте</span><span>sie / Sie</span><strong>stehen</strong><span>вони / Ви стоїте</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — співати</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>обпалити</strong><span>я співаю</span><span>du</span><strong>співає</strong><span>ти співаєш</span><span>er / sie</span><strong>singt</strong><span>він/вона співає</span><span>wir</span><strong>singen</strong><span>ми співаємо</span><span>ihr</span><strong>singt</strong><span>ти співаєш</span><span>sie / Sie</span><strong>singen</strong><span>вони / Ви співаєте</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Приклади</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>імена</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>У дужках подано латиські літери орієнтовну вимову слів.<br>Цього також слід дотримуватися на майбутніх лекціях.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (вір) — ми</div><div class=\"kurss-example\">У слові «wir» літера і вимовляється протяжно.</div><div class=\"kurss-example\">kommen (комен) — прийти</div><div class=\"kurss-example\">gehen (ґе-ен) — йде</div><div class=\"kurss-example\">stehen (ште-ен) — стояти</div><div class=\"kurss-example\">singen (зінґен) — співати</div><div class=\"kurss-example\">du (ду) kommst — ти приходиш</div><div class=\"kurss-example\">er (ер) kommt — він іде</div><div class=\"kurss-example\">sie (зі) kommt - вона йде</div><div class=\"kurss-example\">wer (вер) — хто?</div><div class=\"kurss-example\">ja (я) — так</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Вимова</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">На лекціях дається правильна вимова слів, позначених латиськими літерами.</div><div class=\"kurss-example\">Wir (вір) — ми. У слові wir ī завжди вимовляється протяжно.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Інфінітив</h4><div class=\"lesson1-grammar-note\">Основна форма дієслова. Зазвичай інфінітив закінчується на -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Теперішній часs закінчення</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>видалити <span class=\"lesson1-ending-accent\">- en</span> від форми основи дієслова і допишіть закінчення.</strong></p><p>Приклад: kommen → komm + закінчення</p><div class=\"lesson1-ending-process\" aria-label=\"Теперішній часs процес закінчення\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>основна форма</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>видалити <span class=\"lesson1-ending-accent\">- en</span></strong><span>залишається корінь</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>корінь</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>покласти цьому край</strong><span>e / год / т</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">вул</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Приклади</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Питальні речення</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>У німецькому питальному реченні дієслово зазвичай переміщується на першу позицію.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">латиською:<br>ти приходиш<br>ти йдеш?</div><div class=\"kurss-example\">німецькою мовою:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — ти приходиш<br>kommst du? — ти йдеш?</div><div class=\"kurss-example\">er singt - співає він<br>singt er? — він співає?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Особиста відмінність</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt - він іде</div><div class=\"kurss-example\">sie kommt - вона йде</div><div class=\"kurss-example\">sie kommen - вони / вони йдуть</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Перекласти</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Лекція 1 навчальна картка\">\n                    <span class=\"lesson1-training-progress\">Лекція 1 · Переклад: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">ти йдеш?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Натисніть на картку, щоб побачити переклад німецькою мовою. Після відповіді наступне клацання показує наступну картку.</p>\n                </div>\n              </div>\n            </details>"
};

